mapper.select:
SELECT es.*, e.name AS exam_name, s.student_name AS student_name, s.student_code AS student_number, c.class_name AS class_name FROM exam_score es LEFT JOIN exam e ON e.id = es.exam_id LEFT JOIN student s ON s.id = es.student_id LEFT JOIN class_info c ON c.id = es.class_id WHERE 1=1
AND es.exam_id = #{query.examId}
AND es.class_id = #{query.classId}
AND s.student_name LIKE CONCAT('%', #{query.studentName}, '%')
AND s.student_code = #{query.studentNumber}
ORDER BY es.total_score DESC, es.grade_rank ASC
